window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q788","domains":[3],"level":5,"tag":"ALL","q":"Which statement distinguishes requirements from designs in the Standard?","opts":["Requirements describe project outputs; designs define business value","Requirements represent needs; designs describe a solution approach that satisfies those needs","Requirements are implementation plans; designs are stakeholder problems","Requirements and designs are interchangeable labels for the same artifact"],"answer":[1],"why":["Neither statement captures their distinction.","Correct: requirements represent needs and designs describe a way to satisfy them.","This reverses the distinction.","The Standard says they are related but serve unique purposes."],"ref":"Business Analysis Standard v2 §4.4, printed pp. 16–18","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q789","domains":[3],"level":1,"tag":"ALL","q":"Which requirement type captures goals, objectives, and outcomes explaining why a change was initiated?","opts":["Solution requirements","Transition requirements","Business requirements","Stakeholder requirements"],"answer":[2],"why":["Solution requirements describe capabilities or qualities of the solution.","Transition requirements support moving from current to future state.","Correct: business requirements state goals, objectives, and outcomes for the change.","Stakeholder requirements express stakeholder needs to meet business requirements."],"ref":"Business Analysis Standard v2 §4.4, printed pp. 16–18","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q790","domains":[3],"level":2,"tag":"ALL","q":"Which statements about solution requirements are correct?","opts":["They include functional and non-functional requirements","They bridge business and stakeholder requirements","They specify temporary capabilities needed to transition to the future state","They describe capabilities and qualities of a solution"],"answer":[0,3],"why":["Correct: functional and non-functional requirements are solution requirement categories.","The bridge role is associated with stakeholder requirements.","That describes transition requirements.","Correct: solution requirements describe capabilities and qualities."],"ref":"Business Analysis Standard v2 §4.4, printed pp. 16–18","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q791","domains":[3],"level":3,"tag":"ALL","q":"What does the Standard say traceability enables teams to track?","opts":["Relationships between requirements and designs from the original stakeholder need to the implemented solution","Only the sequence in which requirements are approved","Only dependencies among solution components after implementation","The status of stakeholder engagement activities"],"answer":[0],"why":["Correct: traceability follows relationships from need through implementation.","Approval sequence is not its definition.","Traceability also covers needs and work products, not only post-implementation components.","This is stakeholder engagement tracking."],"ref":"Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed p. 18","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q792","domains":[1],"level":4,"tag":"ALL","q":"Which requirement classification is correctly matched?","opts":["Solution requirement—temporary capability needed only during transition","Transition requirement—capability needed to move from the current state to the future state","Stakeholder requirement—goal explaining why the change was initiated","Business requirement—capability or quality of the solution"],"answer":[1],"why":["That describes a transition requirement.","Correct: transition requirements support the movement between states.","That describes a business requirement.","That describes a solution requirement."],"ref":"Business Analysis Standard v2 §§5.1–5.3, printed pp. 21–22","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q793","domains":[3,9],"level":5,"tag":"ALL","q":"What is the purpose of Plan Business Analysis Approach in BABOK?","opts":["Plan an approach to establish stakeholder relationships","Define the solution scope and business requirements","Define an appropriate method to conduct business analysis activities","Define how BA information will be stored and accessed"],"answer":[2],"why":["That is Plan Stakeholder Engagement.","Solution scope and business requirements are addressed in other tasks.","Correct: that is the task purpose in §3.1.","That is Plan Business Analysis Information Management."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q794","domains":[3,9],"level":1,"tag":"ALL","q":"Which are elements of the Business Analysis Approach output?","opts":["Timing and sequencing of work","Deliverables and techniques that may be used","Approved requirements and designs","Activities and who will perform them"],"answer":[0,1,3],"why":["Correct: timing and sequencing are included.","Correct: deliverables and techniques are identified.","Approval is a separate task output.","Correct: the approach identifies activities and responsible people."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q795","domains":[3],"level":2,"tag":"ALL","q":"Which are inputs to Plan Business Analysis Information Management?","opts":["Business Analysis Approach","Governance Approach","Stakeholder Engagement Approach","Requirements (approved)"],"answer":[0,1,2],"why":["Correct: it informs consistency across the approaches.","Correct: governance defines decisions, approvals, and priorities.","Correct: stakeholder communication and collaboration needs inform information management.","Approved requirements are not a listed input."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q796","domains":[3],"level":3,"tag":"ALL","q":"What is the output of Plan Business Analysis Information Management?","opts":["Stakeholder Engagement Approach","Information Management Approach","Governance Approach","Business Analysis Approach"],"answer":[1],"why":["Stakeholder Engagement Approach addresses relationships and collaboration.","Correct: it defines storage, access, and use of BA information.","Governance Approach defines decision authority and change processes.","Business Analysis Approach describes the overall method for BA work."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q797","domains":[7],"level":4,"tag":"ALL","q":"What is the purpose of Conduct Elicitation?","opts":["Communicate BA information so target stakeholders understand it","Obtain approval of requirements and designs","Draw out, explore, and identify information relevant to the change","Confirm that elicitation results are accurate and consistent"],"answer":[2],"why":["That is Communicate Business Analysis Information.","That is Approve Requirements.","Correct: elicitation draws out, explores, and identifies relevant information.","That is Confirm Elicitation Results."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q798","domains":[7],"level":5,"tag":"ALL","q":"Which statements about Elicitation Results are accurate?","opts":["Confirm Elicitation Results produces confirmed results","Communicate Business Analysis Information produces communicated information","Conduct Elicitation directly produces approved requirements","Conduct Elicitation produces unconfirmed results"],"answer":[0,1,3],"why":["Correct: confirmation produces confirmed results.","Correct: communication produces communicated information.","Approval is a separate task and does not directly result from elicitation.","Correct: elicitation results are initially unconfirmed."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q799","domains":[5],"level":1,"tag":"ALL","q":"What is the purpose of Trace Requirements?","opts":["Ensure requirements and designs are linked to business objectives and solution components","Retain accuracy and consistency of requirements throughout their life cycle","Obtain agreement and approval on requirements","Ensure requirements meet quality standards"],"answer":[0],"why":["Correct: traceability establishes and maintains relationships.","That is Maintain Requirements.","That is Approve Requirements.","That is Verify Requirements."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–83","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q800","domains":[5],"level":2,"tag":"ALL","q":"Which are outputs of Trace Requirements?","opts":["Elicitation Results (confirmed)","Requirements (traced)","Designs (traced)","Requirements (approved)"],"answer":[1,2],"why":["Confirmed elicitation results are produced by Confirm Elicitation Results.","Correct: traced requirements are an output.","Correct: traced designs are an output.","Approved requirements are an output of Approve Requirements."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–83","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q801","domains":[5],"level":3,"tag":"ALL","q":"Which are inputs to Approve Requirements?","opts":["Requirements (verified)","Designs","Governance Approach","Elicitation Results (unconfirmed)"],"answer":[0,1],"why":["Correct: verified requirements are an input.","Correct: Designs are an input when ready for further work.","Governance Approach is a guideline/tool that defines approval authority and process, not an input.","Unconfirmed elicitation results are not listed inputs."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q802","domains":[4,9],"level":4,"tag":"ALL","q":"What is the purpose of Analyze Current State?","opts":["Determine necessary conditions to meet the business need","Assess factors internal to the solution that restrict value","Determine how external factors restrict value realization","Understand why the enterprise needs to change and what the change may affect"],"answer":[3],"why":["That is Define Future State.","That is Assess Solution Limitations.","That is Assess Enterprise Limitations.","Correct: §6.1 investigates reasons for change and direct or indirect effects."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q803","domains":[4,9],"level":5,"tag":"ALL","q":"Which are inputs to Analyze Current State?","opts":["Needs","Elicitation Results","Business Analysis Approach","Solution Recommendation"],"answer":[0,1],"why":["Correct: Needs launch analysis of the current state.","Correct: Elicitation Results help define and understand the current state.","Business Analysis Approach is a guideline/tool for this task, not a listed input.","A Solution Recommendation is produced later in the analysis."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q804","domains":[5],"level":1,"tag":"ALL","q":"Which statement distinguishes Verify Requirements from Validate Requirements?","opts":["Verify traces requirements; Validate maintains them for reuse","Verify checks quality and usability; Validate checks alignment with business goals and stakeholder value","Verify checks alignment with business goals; Validate checks only grammar and format","Verify obtains approval; Validate confirms elicitation results"],"answer":[1],"why":["Trace and Maintain Requirements are separate tasks.","Correct: verification concerns quality and usability; validation concerns value and goal alignment.","This reverses the two task purposes.","Approval and elicitation confirmation are separate tasks."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q805","domains":[5],"level":2,"tag":"ALL","q":"Which are quality characteristics used to verify requirements and designs?","opts":["Consistent","Unambiguous","Atomic","Complete"],"answer":[0,1,2,3],"why":["Correct: consistency is a quality characteristic.","Correct: unambiguous wording is a quality characteristic.","Correct: atomicity is a quality characteristic.","Correct: completeness is a quality characteristic."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q806","domains":[5],"level":3,"tag":"ALL","q":"Which are inputs to Define Requirements Architecture?","opts":["Information Management Approach","Solution Scope","Business Analysis Performance Assessment","Requirements (any state)"],"answer":[0,1,3],"why":["Correct: the approach informs how requirements and models are stored and accessed.","Correct: Solution Scope sets boundaries the architecture must respect.","Performance Assessment is not a listed input to this task.","Correct: requirements in any state may be organized in the architecture."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q807","domains":[6,8],"level":5,"tag":"ALL","q":"What is the output of Assess Solution Limitations?","opts":["Implemented Solution (external)","Solution Limitation","Enterprise Limitation","Solution Performance Analysis"],"answer":[1],"why":["Implemented Solution (external) is an input to the task.","Correct: Solution Limitation describes current constraints and defects within the solution.","Enterprise Limitation is the output of Assess Enterprise Limitations.","Solution Performance Analysis is an input to the task."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q808","domains":[1],"level":1,"tag":"ALL","q":"Which BACCM relationship best expresses how a need relates to change?","opts":["A need motivates stakeholders to act and can cause a change","A need is the value realized after a solution is implemented","A need is the context within which the solution is designed","A need is a stakeholder group affected by a change"],"answer":[0],"why":["Correct: needs can cause changes by motivating stakeholders to act.","This confuses Need with Value.","This confuses Need with Context.","This confuses Need with Stakeholder."],"ref":"Business Analysis Standard v2 §2.2 The BACCM, printed pp. 5–6","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q809","domains":[1],"level":2,"tag":"ALL","q":"Which statements about the BACCM concept Solution are correct?","opts":["A solution is limited to a software application","A solution is a specific way of satisfying one or more needs in a context","A solution can resolve a stakeholder problem","A solution can enable stakeholders to take advantage of an opportunity"],"answer":[1,2,3],"why":["A solution can include processes, products, services, or other ways of meeting needs.","Correct: this is the Standard’s definition.","Correct: solutions may resolve problems.","Correct: solutions may enable opportunities."],"ref":"Business Analysis Standard v2 §2.2 The BACCM, printed pp. 5–6","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q810","domains":[1],"level":3,"tag":"ALL","q":"Which are stated uses of the BACCM?","opts":["Replace the need to tailor business analysis to context","Evaluate the impact of the concepts and their relationships","Communicate business analysis using a common language","Evaluate relationships among the six core concepts"],"answer":[1,2,3],"why":["The BACCM informs analysis; it does not eliminate context-sensitive tailoring.","Correct: assessing impact is a stated use.","Correct: the Standard identifies shared language as a use.","Correct: the model helps assess relationships among the concepts."],"ref":"Business Analysis Standard v2 §2.3 Using the BACCM, printed p. 6","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q811","domains":[2],"level":4,"tag":"ALL","q":"Which principle emphasizes looking beyond a single requirement to the broader situation and why change is needed?","opts":["Get real using examples","Avoid waste","Understand what is doable","See the whole"],"answer":[3],"why":["This principle uses real examples to build understanding.","Avoid waste reduces unnecessary work.","Understand what is doable considers feasibility.","Correct: See the whole focuses on needs in the larger context and why change is necessary."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q812","domains":[2],"level":5,"tag":"ALL","q":"Which actions align with Analyze to determine what is valuable?","opts":["Continuously assess and prioritize work","Maximize value being delivered","Prioritize work solely by ease of implementation","Understand value through context, needs, stakeholders, and solution possibilities"],"answer":[0,1,3],"why":["Correct: continual assessment and prioritization support value.","Correct: the principle aims to maximize delivered value.","Ease may be considered but is not the sole basis for prioritization.","Correct: value is understood through these connected concepts."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q813","domains":[2],"level":1,"tag":"ALL","q":"Which principle uses real examples to build shared understanding and can help derive acceptance criteria?","opts":["Stimulate collaboration and continuous improvement","Get real using examples","Think as a customer","See the whole"],"answer":[1],"why":["This focuses on collaboration and learning.","Correct: the principle uses examples to understand needs and how solutions satisfy them.","This focuses on customer experience and needs.","This focuses on big-picture context."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q814","domains":[3],"level":2,"tag":"ALL","q":"Which approach is typically associated with defining work in iterations and adjusting from feedback?","opts":["Sequential-only","Baseline-driven","Adaptive","Predictive"],"answer":[2],"why":["Sequential-only is not the named approach described.","Baseline-driven reflects predictive planning, not iterative adaptation.","Correct: adaptive approaches deliver value in prioritized increments and learn from feedback.","Predictive approaches plan the work up front."],"ref":"Business Analysis Standard v2 §4.2 Predictive and Adaptive Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q815","domains":[3],"level":3,"tag":"ALL","q":"Which statement describes stakeholder requirements?","opts":["Goals, objectives, and outcomes explaining why a change began","Capabilities and qualities of a solution","Temporary capabilities needed to move between states","Needs of stakeholders that must be met to achieve business requirements"],"answer":[3],"why":["This describes business requirements.","This describes solution requirements.","This describes transition requirements.","Correct: this is the Standard’s description of stakeholder requirements."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q816","domains":[3],"level":4,"tag":"ALL","q":"Which statements about functional and non-functional requirements are accurate?","opts":["Both are categories of solution requirements","Functional requirements describe capabilities or behaviours","Non-functional requirements describe qualities or conditions of a solution","Both describe why the change was initiated"],"answer":[0,1,2],"why":["Correct: functional and non-functional are solution requirement categories.","Correct: functional requirements specify solution behaviour or capability.","Correct: non-functional requirements specify solution qualities or conditions.","The reason for change is expressed through business requirements."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q817","domains":[3],"level":5,"tag":"ALL","q":"What is the purpose of transition requirements?","opts":["Describe the reason a change was initiated","Describe temporary capabilities needed to transition from the current state to the future state","Describe enduring solution capabilities and qualities","Bridge stakeholder needs to business goals"],"answer":[1],"why":["This describes business requirements.","Correct: transition requirements address capabilities needed for the move between states.","This describes solution requirements.","Stakeholder requirements bridge business and solution requirements."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q818","domains":[1],"level":1,"tag":"ALL","q":"Which components appear in the Standard’s task card structure?","opts":["Elements, guidelines and tools, techniques, and stakeholders","Certification exam weighting and scoring rules","Purpose and description","Inputs and outputs"],"answer":[0,2,3],"why":["Correct: these are also task card sections.","Exam scoring is not part of the task card structure.","Correct: purpose and description are part of the task card.","Correct: the task card identifies inputs and outputs."],"ref":"Business Analysis Standard v2 §5.2 Task Card Structure, printed p. 21","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q819","domains":[1],"level":2,"tag":"ALL","q":"In a Standard task card, what do the input and output labels identify?","opts":["The techniques selected and the stakeholder groups consulted","The task purpose and its elements","The governance approval and acceptance criteria","Information entering the task and the work product or result produced"],"answer":[3],"why":["These may appear in other task card sections but do not define inputs/outputs.","Purpose and elements are separate task card components.","Governance and criteria may be relevant, but they do not define the labels.","Correct: inputs are used by the task; outputs are the resulting information or work product."],"ref":"Business Analysis Standard v2 §5.2 Task Card Structure, printed p. 21","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q820","domains":[7],"level":3,"tag":"ALL","q":"What is the purpose of Plan Stakeholder Engagement?","opts":["Plan an approach for establishing and maintaining effective working relationships with stakeholders","Determine which requirements are approved","Plan how BA information is stored and accessed","Confirm that elicitation results are accurate"],"answer":[0],"why":["Correct: this is the purpose of §3.2.","This is Approve Requirements.","This is Plan Business Analysis Information Management.","This is Confirm Elicitation Results."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q821","domains":[7],"level":4,"tag":"ALL","q":"Which are inputs to Plan Stakeholder Engagement?","opts":["Solution Performance Analysis","Needs","Business Analysis Approach","Requirements (approved)"],"answer":[1,2],"why":["Solution Performance Analysis is not a listed input.","Correct: the need and affected parts of the enterprise help identify stakeholders.","Correct: the overall approach should align stakeholder analysis and engagement.","Approved requirements are not a listed input."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q822","domains":[7],"level":5,"tag":"ALL","q":"Which output identifies stakeholders, analyzed characteristics, roles, and engagement approaches?","opts":["Information Management Approach","Business Analysis Approach","Stakeholder Engagement Approach","Governance Approach"],"answer":[2],"why":["Information Management Approach covers storage and access of BA information.","Business Analysis Approach defines the method for BA work.","Correct: this is the output of Plan Stakeholder Engagement.","Governance Approach defines decision authority and processes."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q823","domains":[7],"level":1,"tag":"ALL","q":"What is the purpose of Plan Business Analysis Governance?","opts":["Define how requirements are verified for quality","Define how stakeholders are identified and analyzed","Define how business analysis information is stored","Define how decisions are made about business analysis work, including approvals and change control"],"answer":[3],"why":["This describes Verify Requirements.","This describes Plan Stakeholder Engagement.","This describes Plan Business Analysis Information Management.","Correct: governance establishes decision-making, approvals, priorities, and change control."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q824","domains":[7],"level":2,"tag":"ALL","q":"Which decisions are addressed by the Governance Approach?","opts":["Who has authority to make decisions and approve changes","How priorities are set for business analysis information","How changes to requirements and designs are managed","Which solution will necessarily be selected"],"answer":[0,1,2],"why":["Correct: governance identifies decision authority.","Correct: governance defines the process for setting priorities.","Correct: governance covers change management processes for requirements and designs.","Governance defines decision processes; it does not predetermine the selected solution."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q825","domains":[5],"level":3,"tag":"ALL","q":"What is the purpose of Confirm Elicitation Results?","opts":["Obtain approval of requirements and designs","Check elicitation information for accuracy and consistency with other information","Draw out and explore information relevant to a change","Package BA information for stakeholder understanding"],"answer":[1],"why":["This is Approve Requirements.","Correct: confirmation checks accuracy and consistency.","This is Conduct Elicitation.","This is Communicate Business Analysis Information."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–67","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q826","domains":[5],"level":4,"tag":"ALL","q":"Which input and output are correctly matched to Confirm Elicitation Results?","opts":["Business Analysis Information is an input; Business Analysis Information (communicated) is an output","Elicitation Activity Plan is an input; Stakeholder Engagement is an output","Elicitation Results (unconfirmed) is an input; Elicitation Results (confirmed) is an output","Requirements (verified) is an input; Requirements (approved) is an output"],"answer":[2],"why":["This describes communication, not confirmation.","Stakeholder Engagement is associated with Manage Stakeholder Collaboration.","Correct: confirmation starts from unconfirmed elicitation results and produces confirmed results.","This combines Verify Requirements and Approve Requirements."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–67","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q827","domains":[7],"level":5,"tag":"ALL","q":"What is the purpose of Communicate Business Analysis Information?","opts":["Confirm elicitation information is accurate","Maintain requirements for reuse","Obtain formal approval of requirements","Ensure stakeholders have a shared understanding of business analysis information"],"answer":[3],"why":["This is Confirm Elicitation Results.","This is Maintain Requirements.","This is Approve Requirements.","Correct: communication supports shared understanding of BA information."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q828","domains":[7],"level":1,"tag":"ALL","q":"Which condition best indicates that Business Analysis Information (communicated) has been achieved?","opts":["Target stakeholders understand the content and implications","The information has been sent to all stakeholders","A formal document has been stored in a repository","The information has received approval"],"answer":[0],"why":["Correct: communicated information means the intended audience understands its content and implications.","Sending alone does not establish understanding.","Storage alone does not communicate information.","Approval is a separate activity and not required to define communicated information."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q829","domains":[5],"level":2,"tag":"ALL","q":"Which are outputs of Maintain Requirements?","opts":["Designs (verified)","Requirements (maintained)","Designs (maintained)","Requirements (approved)"],"answer":[1,2],"why":["Verified designs are associated with Verify Requirements, not Maintain Requirements.","Correct: Requirements (maintained) is an output.","Correct: Designs (maintained) is an output.","Approved requirements are produced by Approve Requirements."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q830","domains":[4],"level":3,"tag":"ALL","q":"What is the purpose of Define Future State?","opts":["Identify the internal factors limiting solution value","Assess whether requirements align with business goals","Determine the set of necessary conditions to meet the business need","Understand why the enterprise needs to change"],"answer":[2],"why":["This is Assess Solution Limitations.","This is Validate Requirements.","Correct: this is the purpose of §6.2.","This is Analyze Current State."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q831","domains":[4],"level":4,"tag":"ALL","q":"Which is a listed input to Define Future State?","opts":["Business Requirements","Needs","Current State Description","Elicitation Results (confirmed)"],"answer":[0],"why":["Correct: Business Requirements describe the problems, opportunities, or constraints that the future state will address.","Needs motivate analysis, but the listed §6.2 input is Business Requirements.","Current State Description is a guideline/tool for defining the future state, not a listed input.","Confirmed elicitation results are not a listed input to §6.2."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q832","domains":[4],"level":5,"tag":"ALL","q":"Which output expresses goals and objectives that demonstrate how the future state addresses the business need?","opts":["Business Objectives","Current State Description","Requirements (maintained)","Solution Limitation"],"answer":[0],"why":["Correct: Business Objectives describe the desired outcomes that the future state should achieve.","This describes the existing enterprise context.","This is an output of Maintain Requirements.","This is an output of Assess Solution Limitations."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q833","domains":[5],"level":1,"tag":"ALL","q":"What is the purpose of Validate Requirements?","opts":["Obtain stakeholder agreement and approval","Ensure requirements and designs align with business goals and support delivery of value to stakeholders","Ensure requirements and designs meet quality standards and are usable","Confirm elicitation results are accurate and consistent"],"answer":[1],"why":["This is Approve Requirements.","Correct: validation checks alignment to business goals and stakeholder value.","This is Verify Requirements.","This is Confirm Elicitation Results."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q834","domains":[5],"level":2,"tag":"ALL","q":"Which input/output pairing is correct for Validate Requirements?","opts":["Requirements (approved) is the input; Requirements (verified) is the output","Needs is the input; Current State Description is the output","Requirements (verified) and Designs (verified) are inputs; Requirements (validated) and Designs (validated) are outputs","Requirements (unconfirmed) is an input; Elicitation Results (confirmed) is the output"],"answer":[2],"why":["This reverses the verification and approval states.","This combines inputs and outputs from Analyze Current State.","Correct: verified requirements and designs are validated against business goals and value; validated versions are outputs.","This is Confirm Elicitation Results."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q835","domains":[9],"level":3,"tag":"ALL","q":"Which are inputs to Assess Enterprise Limitations?","opts":["Implemented or Constructed Solution (external)","Solution Performance Analysis","Business Analysis Approach","Current State Description"],"answer":[0,1,3],"why":["Correct: an existing external solution is assessed.","Correct: analysis results help identify enterprise limitations affecting performance.","Business Analysis Approach is not a listed input to this task.","Correct: it provides current internal, environmental, and cultural context."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182","multi":true,"sourceSet":"ecba-set-19.html"},{"id":"q836","domains":[9],"level":4,"tag":"ALL","q":"What is the output of Assess Enterprise Limitations?","opts":["Enterprise Limitation","Solution Limitation","Current State Description","Solution Performance Analysis"],"answer":[0],"why":["Correct: Enterprise Limitation describes current enterprise limitations and their effects on solution performance.","Solution Limitation is produced by Assess Solution Limitations.","Current State Description is an input to this task and an output of Analyze Current State.","Solution Performance Analysis is an input to the assessment."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q837","domains":[2],"level":5,"tag":"ALL","q":"What does the “Think as a customer” principle ask the team to do?","opts":["Begin with detailed solution requirements before considering customer outcomes","Understand customer experience needs and build solutions that address those needs","Prioritize all work by delivery speed regardless of customer impact","Represent every stakeholder as a customer with identical needs"],"answer":[1],"why":["The Standard describes starting with a high-level view of customer needs and then developing detail.","Correct: the principle focuses on understanding customer experience needs and addressing them.","Speed may matter, but it does not replace value to customers.","Stakeholders can have different needs and perspectives."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":false,"sourceSet":"ecba-set-19.html"},{"id":"q838","domains":[1],"level":1,"tag":"ALL","q":"Which statement describes tangible value in the Business Analysis Standard?","opts":["Value that is directly measurable and often has a significant monetary component","Value that is measured indirectly and often has a motivational component","Value that exists only when all stakeholders agree","Value that is measured only by project cost"],"answer":[0],"why":["Correct: the Standard characterizes tangible value as directly measurable and often monetary.","This describes intangible value.","Stakeholder agreement may matter but does not define tangible value.","Tangible value is not limited to project cost."],"ref":"Business Analysis Standard v2 §2.2 The BACCM, printed pp. 5–6","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q839","domains":[1],"level":2,"tag":"ALL","q":"Which statements about intangible value are accurate?","opts":["It must be expressed as a monetary amount","It is measured indirectly","It often has a significant motivational component","It can include reputation or employee morale"],"answer":[1,2,3],"why":["This describes the monetary emphasis of tangible value.","Correct: intangible value is measured indirectly.","Correct: it often has a motivational component.","Correct: reputation and morale are examples."],"ref":"Business Analysis Standard v2 §2.2 The BACCM, printed pp. 5–6","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q840","domains":[1],"level":3,"tag":"ALL","q":"Which BACCM concept is defined as “the act of transformation in response to a need”?","opts":["Value","Context","Change","Need"],"answer":[2],"why":["Value is worth, importance, or usefulness.","Context is the circumstances relevant to change.","Correct: this is the Standard’s definition of Change.","A Need is a problem or opportunity."],"ref":"Business Analysis Standard v2 §2.2 The BACCM, printed pp. 5–6","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q841","domains":[1],"level":4,"tag":"ALL","q":"Which statement about evaluating BACCM concepts is correct?","opts":["Each concept is analyzed independently to avoid overlap","The model applies only to software projects","The model replaces elicitation and collaboration","The concepts are considered in relationship to one another"],"answer":[3],"why":["The model explicitly supports considering relationships.","The Standard says the fundamentals apply across initiatives and contexts.","The model supports analysis; it does not replace tasks.","Correct: the BACCM is used to evaluate relationships among its concepts."],"ref":"Business Analysis Standard v2 §2.3 Using the BACCM, printed p. 6","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q842","domains":[2],"level":5,"tag":"ALL","q":"Which principle encourages the team to focus on feasibility and what can realistically be achieved?","opts":["Understand what is doable","Analyze to determine what is valuable","Think as a customer","See the whole"],"answer":[0],"why":["Correct: this principle considers feasibility and what is achievable.","This principle focuses on prioritizing value.","This principle focuses on customer experience.","This principle considers the broader context and need for change."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q843","domains":[2],"level":1,"tag":"ALL","q":"Which actions reflect Stimulate collaboration and continuous improvement?","opts":["Treat the first analysis as final and unchangeable","Encourage stakeholder collaboration","Use feedback and learning to improve the work","Avoid stakeholder involvement until the solution is complete"],"answer":[1,2],"why":["Continuous improvement allows learning and adjustment.","Correct: collaboration is explicit in the principle.","Correct: continuous improvement relies on feedback and learning.","The principle promotes collaboration rather than postponing it."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q844","domains":[2],"level":2,"tag":"ALL","q":"What does Avoid waste emphasize?","opts":["Choose the lowest-cost option regardless of stakeholder value","Avoid revisiting decisions even when new evidence appears","Reduce work that does not contribute to useful outcomes or value","Eliminate all analysis and documentation"],"answer":[2],"why":["Lowest cost alone does not determine value.","New evidence may justify revisiting decisions.","Correct: avoiding waste means limiting unnecessary effort while preserving value.","Analysis and documentation should be appropriate, not eliminated wholesale."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q845","domains":[3],"level":3,"tag":"ALL","q":"Which statement best describes a hybrid approach?","opts":["It requires all work to be planned in detail up front","It delivers only fixed-scope increments without adaptation","It is a standard term for a project with multiple stakeholders","It combines predictive and adaptive elements to suit the initiative"],"answer":[3],"why":["This describes a predictive emphasis.","This is not the definition of hybrid.","Stakeholder count does not define the approach.","Correct: hybrid approaches combine elements of predictive and adaptive ways of working."],"ref":"Business Analysis Standard v2 §4.2 Predictive and Adaptive Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q846","domains":[3],"level":4,"tag":"ALL","q":"How are requirements described in the Standard?","opts":["A usable representation of a need","A set of tasks that implement a selected solution","A measure of actual solution performance","A record of stakeholder approvals"],"answer":[0],"why":["Correct: the Standard describes a requirement as a usable representation of a need.","Tasks are activities, not requirements.","Performance measures assess solution outcomes.","Approval records are governance information."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q847","domains":[3],"level":5,"tag":"ALL","q":"Which statement about designs is accurate?","opts":["Designs replace business requirements after approval","Designs describe a solution approach and can model structure, components, or architecture","Designs capture only stakeholder needs without proposing a solution","Designs are limited to technical diagrams"],"answer":[1],"why":["Requirements and designs serve distinct purposes and can both remain relevant.","Correct: designs transform requirements into actionable initiatives, plans, and systems and can model solution structure.","This describes requirements more closely.","Designs may be models or artifacts and are not limited to technical diagrams."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q848","domains":[3],"level":1,"tag":"ALL","q":"Which requirement type describes solution capabilities or qualities needed to meet stakeholder requirements?","opts":["Stakeholder requirements","Transition requirements","Solution requirements","Business requirements"],"answer":[2],"why":["Stakeholder requirements express needs to meet business requirements.","Transition requirements support moving between states.","Correct: solution requirements describe capabilities and qualities of a solution.","Business requirements explain why the change began."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q849","domains":[3],"level":2,"tag":"ALL","q":"Which traceability direction links a requirement or design back to its original business need?","opts":["Forward traceability","Lateral traceability","Release traceability","Backward traceability"],"answer":[3],"why":["Forward traceability follows toward solution components.","Lateral relationships connect related requirements and designs.","Release traceability is not the named direction in this description.","Correct: backward traceability follows the work product back to its source need."],"ref":"Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed p. 18","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q850","domains":[3],"level":3,"tag":"ALL","q":"Which benefits are supported by traceability?","opts":["Identify the source of a requirement or design","Understand other related work products potentially affected by change","Support impact, scope, change, risk, time, cost, or communication management","Determine that every requirement must be implemented"],"answer":[0,1,2],"why":["Correct: traceability helps identify lineage and source.","Correct: related items potentially affected by change can be identified.","Correct: the Standard lists these management benefits.","Traceability does not itself require every requirement to be implemented."],"ref":"Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed p. 18","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q851","domains":[7],"level":4,"tag":"ALL","q":"What is the purpose of Plan Business Analysis Governance?","opts":["Define how requirements are prioritized by value","Define how decisions are made about business analysis work, including approvals and change control","Define the method for conducting business analysis activities","Define how business analysis information is stored and accessed"],"answer":[1],"why":["Prioritization is a separate task, though governance may define decision authority.","Correct: governance defines decision-making authority and processes for BA work and changes.","That is Plan Business Analysis Approach.","That is Plan Business Analysis Information Management."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q852","domains":[7],"level":5,"tag":"ALL","q":"Which are concerns addressed by the Governance Approach?","opts":["The process for managing requirements and design changes","Detailed solution performance measures","Decision authority and responsibility","Approval of business analysis information"],"answer":[0,2,3],"why":["Correct: it defines the change management process across the initiative.","Performance measures are not the purpose of the Governance Approach.","Correct: governance identifies who has decision authority and responsibility.","Correct: it defines who approves BA information."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q853","domains":[7],"level":1,"tag":"ALL","q":"What is the purpose of Prepare for Elicitation?","opts":["Draw out information from stakeholders during an elicitation activity","Confirm elicitation results for accuracy and consistency","Communicate BA information for stakeholder understanding","Understand the scope of elicitation and select appropriate techniques to conduct it"],"answer":[3],"why":["This is Conduct Elicitation.","This is Confirm Elicitation Results.","This is Communicate Business Analysis Information.","Correct: preparation determines the scope and approach for elicitation."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q854","domains":[7],"level":2,"tag":"ALL","q":"Which output is associated with Prepare for Elicitation?","opts":["Elicitation Activity Plan","Elicitation Results (confirmed)","Business Analysis Information (communicated)","Stakeholder Engagement"],"answer":[0],"why":["Correct: the Elicitation Activity Plan records planned activities, techniques, logistics, scope, and background sources.","Confirmed results are produced by Confirm Elicitation Results.","Communicated information is produced by Communicate Business Analysis Information.","Stakeholder Engagement is associated with Manage Stakeholder Collaboration."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q855","domains":[7],"level":3,"tag":"ALL","q":"Which statements describe the Elicitation Activity Plan?","opts":["It records final approval of requirements","It can identify activities and techniques","It can describe logistics and scope","It can identify available background information"],"answer":[1,2,3],"why":["Approval is a separate task.","Correct: activities and techniques are included in the plan.","Correct: logistics and scope are part of planning.","Correct: background sources may be identified."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q856","domains":[5],"level":4,"tag":"ALL","q":"What does Confirm Elicitation Results assess?","opts":["Whether requirements have formal approval","Whether the business analysis approach is feasible","Accuracy and consistency of elicitation information","Whether the solution meets business performance targets"],"answer":[2],"why":["This concerns Approve Requirements.","This concerns Plan Business Analysis Approach.","Correct: confirmation checks elicitation information for accuracy and consistency with other information.","This concerns solution evaluation."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–67","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q857","domains":[5],"level":5,"tag":"ALL","q":"What is the purpose of Prioritize Requirements?","opts":["Confirm requirements are accurate and consistent","Ensure requirements meet quality standards","Obtain stakeholder approval of requirements","Rank requirements according to relative importance"],"answer":[3],"why":["This is Confirm Elicitation Results.","This is Verify Requirements.","This is Approve Requirements.","Correct: prioritization ranks requirements by relative importance."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q858","domains":[5],"level":1,"tag":"ALL","q":"Which factors may be considered when prioritizing requirements?","opts":["Benefit","Penalty if not implemented","Cost","Risk"],"answer":[0,1,2,3],"why":["Correct: benefit may inform relative priority.","Correct: penalty for not implementing can affect priority.","Correct: cost is a prioritization consideration.","Correct: risk can inform prioritization."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q859","domains":[4],"level":2,"tag":"ALL","q":"What is the purpose of Assess Risks?","opts":["Obtain approval for the change strategy","Understand undesirable consequences of internal and external forces during transition to or within the future state","Identify opportunities that should be treated as positive risks","Measure actual solution performance against expected measures"],"answer":[1],"why":["Approval is a governance/approval activity, not the purpose of risk assessment.","Correct: this is the purpose of §6.3.","BABOK distinguishes opportunities as needs; this task focuses on undesirable consequences.","This is Measure Solution Performance."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–124","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q860","domains":[4],"level":3,"tag":"ALL","q":"Which factors are considered when analyzing a risk?","opts":["Likelihood of the risk","Potential time frame when it might occur","Possible consequences if it occurs","Impact of those consequences"],"answer":[0,1,2,3],"why":["Correct: likelihood is analyzed.","Correct: potential timing is analyzed.","Correct: consequences are analyzed.","Correct: impact is analyzed."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–124","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q861","domains":[5],"level":4,"tag":"ALL","q":"What is the purpose of Specify and Model Requirements?","opts":["Obtain approval of requirements and designs","Maintain requirement accuracy to support reuse","Trace requirements to solution components","Analyze, synthesize, and refine elicitation results into requirements and designs"],"answer":[3],"why":["This is Approve Requirements.","This is Maintain Requirements.","This is Trace Requirements.","Correct: specifying and modeling transforms elicitation information into structured requirements and designs."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q862","domains":[5],"level":5,"tag":"ALL","q":"Which are requirement classifications used in BABOK?","opts":["Business requirements","Stakeholder requirements","Solution requirements","Transition requirements"],"answer":[0,1,2,3],"why":["Correct: business requirements are a classification.","Correct: stakeholder requirements are a classification.","Correct: solution requirements are a classification.","Correct: transition requirements are a classification."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q863","domains":[6,8],"level":1,"tag":"ALL","q":"What is the purpose of Define Design Options?","opts":["Verify requirements against quality characteristics","Define solution approaches, identify solution components, and represent them in design options","Determine the current state and the reason for change","Measure solution performance"],"answer":[1],"why":["This is Verify Requirements.","Correct: the task defines options for how a solution could be realized.","This is Analyze Current State.","This is Measure Solution Performance."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–157","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q864","domains":[6,8],"level":2,"tag":"ALL","q":"Which output is directly associated with Define Design Options?","opts":["Solution Limitation","Elicitation Results (confirmed)","Design Options","Requirements (verified)"],"answer":[2],"why":["Solution Limitation is produced by Assess Solution Limitations.","Confirmed elicitation results are produced by Confirm Elicitation Results.","Correct: Design Options are the task output.","Verified requirements are produced by Verify Requirements."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–157","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q865","domains":[6,8],"level":3,"tag":"ALL","q":"What is the purpose of Measure Solution Performance?","opts":["Analyze stakeholder needs and define business requirements","Identify the internal solution factors restricting value","Obtain approval for proposed requirements","Define performance measures and assess solution performance against them"],"answer":[3],"why":["This describes current-state/business requirements analysis.","This is Assess Solution Limitations.","This is Approve Requirements.","Correct: the task measures and assesses performance to determine how well a solution is delivering value."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170","multi":false,"sourceSet":"ecba-set-20.html"},{"id":"q866","domains":[6,8],"level":4,"tag":"ALL","q":"Which concepts distinguish performance measures from performance metrics?","opts":["Performance measures are quantifiable indicators used to assess solution performance","Performance metrics provide a way to measure a specific aspect of solution performance","Both terms refer only to qualitative stakeholder opinions","A measure is an output of requirements approval"],"answer":[0,1],"why":["Correct: measures are quantifiable indicators of performance.","Correct: metrics quantify a specific aspect of solution performance.","Performance measures are not limited to qualitative opinions.","They relate to solution evaluation, not approval."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q867","domains":[5],"level":5,"tag":"ALL","q":"Which quality characteristics are recognized when verifying requirements and designs?","opts":["Approved","Feasible","Testable","Unambiguous"],"answer":[1,2,3],"why":["Approval is a governance status, not a verification quality characteristic.","Correct: feasibility is a quality characteristic.","Correct: testability is a quality characteristic.","Correct: unambiguous wording is a quality characteristic."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144","multi":true,"sourceSet":"ecba-set-20.html"},{"id":"q868","domains":[1],"level":1,"tag":"ALL","q":"Which parts are included in the Standard’s definition of business analysis?","opts":["Enabling change in an enterprise","Defining needs and recommending solutions","Delivering value to stakeholders within a context","Managing project scope, schedule, and cost"],"answer":[0,1,2],"why":["Correct: enabling change is part of the definition.","Correct: defining needs and recommending solutions are central to the definition.","Correct: value to stakeholders within context completes the definition.","Project management constraints are not the definition of business analysis."],"ref":"Business Analysis Standard v2 §2.1 Defining Business Analysis, printed p. 5","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q869","domains":[1],"level":2,"tag":"ALL","q":"Which statement describes the BACCM concept Need?","opts":["The circumstances that influence and explain a change","A problem or opportunity to be addressed","The worth or usefulness of something to a stakeholder","A specific way of satisfying one or more needs"],"answer":[1],"why":["This describes Context.","Correct: this is the Standard’s definition of Need.","This describes Value.","This describes Solution."],"ref":"Business Analysis Standard v2 §2.2 The BACCM, printed pp. 5–6","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q870","domains":[1],"level":3,"tag":"ALL","q":"Which statement about Stakeholders is consistent with the BACCM?","opts":["They are only the end users of the proposed solution","They are the circumstances surrounding an initiative","They are groups or individuals with a relationship to the change, need, or solution","They are limited to people who approve project deliverables"],"answer":[2],"why":["End users are one stakeholder type, not the full concept.","This describes Context.","Correct: this is the BACCM definition of Stakeholder.","Approval authority is only one possible stakeholder role."],"ref":"Business Analysis Standard v2 §2.2 The BACCM, printed pp. 5–6","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q871","domains":[1],"level":4,"tag":"ALL","q":"Which activities are supported by using the BACCM?","opts":["Identify professional development opportunities","Evaluate the impacts and relationships among core concepts","Determine which solution must be selected in every initiative","Describe effective business analysis using shared concepts"],"answer":[0,1,3],"why":["Correct: identifying development opportunities is a stated use.","Correct: evaluating concept impacts and relationships is a stated use.","BACCM supports analysis and does not dictate a single solution.","Correct: BACCM provides a common model and language for business analysis."],"ref":"Business Analysis Standard v2 §2.3 Using the BACCM, printed p. 6","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q872","domains":[2],"level":5,"tag":"ALL","q":"Which principle guides the team to explore how an example demonstrates the need and how a solution could satisfy it?","opts":["Get real using examples","See the whole","Avoid waste","Think as a customer"],"answer":[0],"why":["Correct: examples build shared understanding of needs and potential solutions.","This principle focuses on context and the broader picture.","This focuses on avoiding unnecessary work.","This focuses on customer experience and needs."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q873","domains":[2],"level":1,"tag":"ALL","q":"Which statements align with See the whole?","opts":["Focus only on the requested feature","Understand needs in the big-picture context","Identify why a change is necessary","Consider relationships among context, solution, and stakeholders when pursuing outcomes"],"answer":[1,2,3],"why":["This narrows analysis and conflicts with the principle.","Correct: the principle calls for a big-picture view.","Correct: identifying why change is necessary is part of this principle.","Correct: outcomes depend on understanding connected core concepts."],"ref":"Business Analysis Standard v2 §3.3 Business Analysis Principles, printed pp. 10–12","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q874","domains":[3],"level":2,"tag":"ALL","q":"When is a predictive approach especially suitable according to the Standard?","opts":["Needs are expected to emerge as a solution is built","The team intends to plan only the upcoming iteration","Work is well-defined and can be completed sequentially","The challenge is poorly defined and uncertainty is high"],"answer":[2],"why":["Emerging needs and uncertainty favor adaptive approaches.","Planning the upcoming iteration first is adaptive.","Correct: the Standard suggests predictive when work is well-defined or sequential.","Adaptive approaches are suited to poorly defined challenges."],"ref":"Business Analysis Standard v2 §4.2 Predictive and Adaptive Approaches, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q875","domains":[3],"level":3,"tag":"ALL","q":"Which description best matches functional requirements?","opts":["Qualities or conditions under which a solution operates","Temporary capabilities needed to transition between states","Goals and outcomes explaining why change began","Capabilities or behaviours a solution must provide"],"answer":[3],"why":["This describes non-functional requirements.","This describes transition requirements.","This describes business requirements.","Correct: functional requirements describe solution behaviour or capabilities."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q876","domains":[3],"level":4,"tag":"ALL","q":"Which statements distinguish business and stakeholder requirements?","opts":["Business requirements state goals, objectives, and outcomes for why change began","Stakeholder requirements express stakeholder needs to be met to achieve business requirements","Business requirements describe detailed solution capabilities","Stakeholder requirements are temporary capabilities for transition"],"answer":[0,1],"why":["Correct: business requirements explain the reason and outcomes for change.","Correct: stakeholder requirements express stakeholder needs that support business requirements.","Detailed solution capabilities are solution requirements.","Temporary transition capabilities are transition requirements."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q877","domains":[3],"level":5,"tag":"ALL","q":"What is the role of transition requirements?","opts":["Describe stakeholder needs that bridge business and solution requirements","Describe temporary capabilities needed to move from current state to future state","Describe enduring business goals and outcomes","Describe functional and quality characteristics of a solution"],"answer":[1],"why":["This describes stakeholder requirements.","Correct: transition requirements support the move between states.","This describes business requirements.","This describes solution requirements."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q878","domains":[3],"level":1,"tag":"ALL","q":"Which statements about requirements and designs are accurate?","opts":["They serve unique purposes even though they are related","A design is always a non-functional requirement","They may be represented as artifacts, documents, or models","The same tasks and techniques may be used to develop both"],"answer":[0,2,3],"why":["Correct: the Standard stresses their distinct purposes.","Designs are not a requirement type.","Correct: both can be represented in several forms.","Correct: overlapping tasks and techniques can be used."],"ref":"Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q879","domains":[1],"level":2,"tag":"ALL","q":"Which concept relationship is represented when a solution satisfies a need by resolving a problem or enabling an opportunity?","opts":["Value and Context only","Stakeholder and Change only","Change and Value only","Need and Solution"],"answer":[3],"why":["Value and context matter but this statement describes Need–Solution relation.","Stakeholder and change do not express this specific relationship.","Change and value do not express this specific relationship.","Correct: a solution addresses a need in a context."],"ref":"Business Analysis Standard v2 §2.3 Using the BACCM, printed p. 6","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q880","domains":[7],"level":3,"tag":"ALL","q":"Which is the purpose of Plan Stakeholder Engagement?","opts":["Plan how to establish and maintain effective working relationships with stakeholders","Define how business analysis decisions and approvals are governed","Determine how BA information is stored and accessed","Confirm that elicitation results are accurate"],"answer":[0],"why":["Correct: this is the purpose of §3.2.","This is Plan Business Analysis Governance.","This is Plan Business Analysis Information Management.","This is Confirm Elicitation Results."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q881","domains":[7],"level":4,"tag":"ALL","q":"Which are considered during stakeholder analysis?","opts":["Whether every stakeholder has approved the requirements","Roles and responsibilities","Attitudes toward the change and collaboration","Decision-making authority"],"answer":[1,2,3],"why":["Approval status is not a defining stakeholder characteristic.","Correct: roles help determine stakeholder contributions.","Correct: attitudes may affect engagement and participation.","Correct: authority is relevant to stakeholder analysis."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q882","domains":[3],"level":5,"tag":"ALL","q":"Which output states how BA information will be organized, stored, accessed, and used?","opts":["Stakeholder Engagement Approach","Governance Approach","Information Management Approach","Business Analysis Approach"],"answer":[2],"why":["This addresses stakeholder relationships and engagement.","This defines decision-making, authority, and change governance.","Correct: the Information Management Approach sets information management methods.","This describes the overall method for BA tasks."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q883","domains":[3],"level":1,"tag":"ALL","q":"Which techniques can help identify information management needs?","opts":["Interviews","Lessons Learned","Acceptance and Evaluation Criteria","Brainstorming"],"answer":[0,1,3],"why":["Correct: Interviews help identify individual needs.","Correct: Lessons Learned can improve the information management approach.","Acceptance and Evaluation Criteria is not a listed technique for this task.","Correct: Brainstorming helps uncover information needs."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q884","domains":[7],"level":2,"tag":"ALL","q":"What is the purpose of Conduct Elicitation?","opts":["Draw out, explore, and identify information relevant to the change","Plan the elicitation scope, logistics, and techniques","Confirm the accuracy and consistency of elicitation results","Communicate information so stakeholders understand its implications"],"answer":[0],"why":["Correct: elicitation draws out and explores relevant information.","This describes Prepare for Elicitation.","This describes Confirm Elicitation Results.","This describes Communicate Business Analysis Information."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q885","domains":[7],"level":3,"tag":"ALL","q":"Which pair correctly matches an elicitation task with its output?","opts":["Manage Stakeholder Collaboration—Elicitation Activity Plan","Conduct Elicitation—Elicitation Results (unconfirmed)","Confirm Elicitation Results—Elicitation Results (unconfirmed)","Conduct Elicitation—Requirements (approved)"],"answer":[1],"why":["Elicitation Activity Plan is associated with Prepare for Elicitation.","Correct: Conduct Elicitation initially produces unconfirmed results.","Confirmation produces Elicitation Results (confirmed).","Approval is a separate task and output."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q886","domains":[7],"level":4,"tag":"ALL","q":"What is the key outcome of Communicate Business Analysis Information?","opts":["Requirements have received formal approval","All stakeholders have participated in elicitation","Target stakeholders understand the information’s content and implications","Information has been transmitted to every stakeholder"],"answer":[2],"why":["Approval is a separate task.","Participation in elicitation is not the outcome of communication.","Correct: communication is effective when target stakeholders understand content and implications.","Transmission alone does not establish shared understanding."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q887","domains":[7],"level":5,"tag":"ALL","q":"Which formats may be used to communicate business analysis information?","opts":["Informal documentation","Presentations","Only a requirements management repository","Formal documentation"],"answer":[0,1,3],"why":["Correct: informal documentation may be appropriate.","Correct: presentations can support understanding or decisions.","A repository is a storage tool, not the only communication format.","Correct: formal documentation is one possible format."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q888","domains":[5],"level":1,"tag":"ALL","q":"What is the purpose of Assess Requirements Changes?","opts":["Evaluate the implications of proposed changes to requirements and designs","Approve all proposed requirement changes automatically","Maintain the accuracy of approved requirements for reuse","Trace every requirement to a solution component"],"answer":[0],"why":["Correct: the task assesses the effect of a proposed change.","Assessment informs decisions; it does not automatically approve changes.","This is Maintain Requirements.","This is Trace Requirements."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–95","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q889","domains":[5],"level":2,"tag":"ALL","q":"Which outcomes may result from a Requirements Change Assessment?","opts":["Automatically implement the change without governance review","Approve the proposed change","Modify the proposed change","Deny the proposed change"],"answer":[1,2,3],"why":["Implementation is not automatic; decisions follow governance and approval processes.","Correct: approval may be recommended.","Correct: modification may be recommended.","Correct: denial may be recommended."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–95","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q890","domains":[4],"level":3,"tag":"ALL","q":"What is the purpose of Define Change Strategy?","opts":["Verify requirements meet quality standards","Measure solution performance after implementation","Determine the most effective approach to implementing the desired future state","Understand why the enterprise needs to change"],"answer":[2],"why":["This is Verify Requirements.","This is Measure Solution Performance.","Correct: the task selects an approach to achieve the future state.","This is Analyze Current State."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q891","domains":[4],"level":4,"tag":"ALL","q":"Which are elements considered when defining a change strategy?","opts":["Assess solution scope","Determine whether a transition state is needed","Approve requirements and designs","Identify alternative change strategies"],"answer":[0,1,3],"why":["Correct: Solution Scope informs the strategy.","Correct: a transition state may be needed to move toward the future state.","Formal approval is a separate task.","Correct: alternatives are identified and evaluated."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q892","domains":[5],"level":5,"tag":"ALL","q":"Which is a purpose of Specify and Model Requirements?","opts":["Analyze, synthesize, and refine elicitation results into requirements and designs","Obtain stakeholder approval of requirements","Determine the future state needed to meet the business need","Assess factors that restrict value realization"],"answer":[0],"why":["Correct: §7.1 turns elicitation information into structured requirements and designs.","This is Approve Requirements.","This is Define Future State.","This is a solution or enterprise limitations assessment."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q893","domains":[5],"level":1,"tag":"ALL","q":"Which are requirement classifications in BABOK?","opts":["Transition","Business","Stakeholder","Solution"],"answer":[0,1,2,3],"why":["Correct: transition requirements are a classification.","Correct: business requirements are a classification.","Correct: stakeholder requirements are a classification.","Correct: solution requirements are a classification."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q894","domains":[6,8],"level":2,"tag":"ALL","q":"What is the purpose of Analyze Potential Value and Recommend Solution?","opts":["Verify requirements and designs against quality standards","Approve the selected requirements for implementation","Estimate the potential value for each design option and recommend the option most likely to deliver value","Define the business need and current-state problem"],"answer":[2],"why":["This is Verify Requirements.","This is Approve Requirements.","Correct: the task analyzes value across options and recommends a solution.","This is Analyze Current State."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q895","domains":[6,8],"level":3,"tag":"ALL","q":"Which output is associated with Analyze Potential Value and Recommend Solution?","opts":["Requirements (verified)","Solution Limitation","Stakeholder Engagement Approach","Solution Recommendation"],"answer":[3],"why":["Verified requirements are produced by Verify Requirements.","Solution Limitation is produced by Assess Solution Limitations.","Stakeholder Engagement Approach is produced by Plan Stakeholder Engagement.","Correct: Solution Recommendation is the output."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q896","domains":[6,8],"level":4,"tag":"ALL","q":"What does Analyze Performance Measures do with solution performance data?","opts":["Analyze measures to understand trends, accuracy, and variances from expected performance","Define how requirements should be stored and accessed","Approve requirements and designs","Determine the business need that initiated a change"],"answer":[0],"why":["Correct: performance analysis examines measures, trends, accuracy, and variances.","This is Plan Business Analysis Information Management.","This is Approve Requirements.","This is Analyze Current State."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–173","multi":false,"sourceSet":"ecba-set-21.html"},{"id":"q897","domains":[6,8],"level":5,"tag":"ALL","q":"Which are relevant when analyzing performance measures?","opts":["Whether every requirement has been approved","Trends over time","Accuracy and reliability of collected data","Variances between expected and actual performance"],"answer":[1,2,3],"why":["Approval status is not a performance-measure analysis factor.","Correct: trends are considered.","Correct: accuracy and reliability matter to valid analysis.","Correct: performance variance is analyzed."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–173","multi":true,"sourceSet":"ecba-set-21.html"},{"id":"q898","domains":[3,9],"level":2,"tag":"ALL","q":"What is the purpose of Plan Business Analysis Approach?","opts":["Define the governance approval process","Define an appropriate method to conduct business analysis activities","Define how BA information will be stored and accessed","Plan effective working relationships with stakeholders"],"answer":[1],"why":["This is Plan Business Analysis Governance.","Correct: this is the purpose of §3.1.","This is Plan Business Analysis Information Management.","This is Plan Stakeholder Engagement."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q899","domains":[1],"level":3,"tag":"ALL","q":"Which output identifies stakeholders, their characteristics and roles, and the engagement approach?","opts":["Business Analysis Approach","Information Management Approach","Stakeholder Engagement Approach","Governance Approach"],"answer":[2],"why":["This defines the method for BA activities.","This defines information storage and access.","Correct: this is the output of Plan Stakeholder Engagement.","This defines decision authority and governance processes."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36; related: Business Analysis Standard v2 §2 Understanding Business Analysis, printed pp. 4–8","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q900","domains":[7],"level":4,"tag":"ALL","q":"Which output defines decision authority, approval responsibility, and the process for managing requirement and design changes?","opts":["Stakeholder Engagement Approach","Information Management Approach","Business Analysis Approach","Governance Approach"],"answer":[3],"why":["This describes stakeholder analysis and engagement.","This describes storage, access, and use of BA information.","This describes how BA activities are performed.","Correct: the Governance Approach records authority, approvals, and change processes."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42","multi":false,"sourceSet":"ecba-set-22.html"}]);